#!/usr/bin/env python3
"""The original room, by day and by night (240x160, one byte a pixel), as drawn by the original's 0x0800D690.
Made by tools/extract_rooms.py. Run this to write ../orig_rooms.h (run-length pairs: count, colour)."""
import os
DAY = bytes.fromhex('')
NIGHT = bytes.fromhex('')
# the colour-map entries it leaves set (CMAP index, value), which later drawing relies on
CMAP = [(46, 0), (69, 1), (97, 17), (98, 18), (99, 19), (101, 1), (103, 21), (107, 2), (109, 1), (110, 1), (111, 1), (112, 24), (113, 25), (114, 20), (115, 23), (119, 2), (120, 12), (121, 22), (122, 26)]
# its last 8 drawings are pictures through draw_sprite, which the game hooks (ext.c): they are made at run time.
# Each: (desc, x, y, scale, flip, limit) and the colour-map entries set just before
SPRITES = [([134283244, 18, 2, 2, 0, 99], [(46, 0), (69, 1), (97, 17), (98, 18), (99, 19), (101, 1), (103, 21), (107, 2), (109, 1), (110, 1), (111, 1), (112, 24), (113, 25), (114, 20), (115, 23), (119, 2), (120, 11), (121, 22), (122, 26)]), ([134283252, 78, 2, 2, 0, 99], [(46, 0), (69, 1), (97, 17), (98, 18), (99, 19), (101, 1), (103, 21), (107, 2), (109, 1), (110, 1), (111, 1), (112, 24), (113, 25), (114, 20), (115, 23), (119, 2), (120, 11), (121, 22), (122, 26)]), ([134283260, 138, 2, 2, 0, 99], [(46, 0), (69, 1), (97, 17), (98, 18), (99, 19), (101, 1), (103, 21), (107, 2), (109, 1), (110, 1), (111, 1), (112, 24), (113, 25), (114, 20), (115, 23), (119, 2), (120, 11), (121, 22), (122, 26)]), ([134283228, 198, 2, 2, 0, 99], [(46, 0), (69, 1), (97, 17), (98, 18), (99, 19), (101, 1), (103, 21), (107, 2), (109, 1), (110, 1), (111, 1), (112, 24), (113, 25), (114, 20), (115, 23), (119, 2), (120, 11), (121, 22), (122, 26)]), ([134283268, 18, 135, 2, 0, 99], [(46, 0), (69, 1), (97, 17), (98, 18), (99, 19), (101, 1), (103, 21), (107, 2), (109, 1), (110, 1), (111, 1), (112, 24), (113, 25), (114, 20), (115, 23), (119, 2), (120, 11), (121, 22), (122, 26)]), ([134283276, 78, 135, 2, 0, 99], [(46, 0), (69, 1), (97, 17), (98, 18), (99, 19), (101, 1), (103, 21), (107, 2), (109, 1), (110, 1), (111, 1), (112, 24), (113, 25), (114, 20), (115, 23), (119, 2), (120, 11), (121, 22), (122, 26)]), ([134283284, 138, 135, 2, 0, 99], [(46, 0), (69, 1), (97, 17), (98, 18), (99, 19), (101, 1), (103, 21), (107, 2), (109, 1), (110, 1), (111, 1), (112, 24), (113, 25), (114, 20), (115, 23), (119, 2), (120, 11), (121, 22), (122, 26)]), ([134283196, 198, 135, 2, 0, 99], [(46, 0), (69, 1), (97, 17), (98, 18), (99, 19), (101, 1), (103, 21), (107, 2), (109, 1), (110, 1), (111, 1), (112, 24), (113, 25), (114, 20), (115, 23), (119, 2), (120, 12), (121, 22), (122, 26)])]

def unrle(b):
    o = bytearray()
    for i in range(0, len(b), 2): o += bytes([b[i + 1]]) * b[i]
    return bytes(o)
if __name__ == '__main__':
    assert len(unrle(DAY)) == len(unrle(NIGHT)) == 38400
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    with open(os.path.join(root, 'orig_rooms.h'), 'w') as h:
        h.write('// The original room by day and by night: run-length pairs (count, colour). Made by gen/orig_rooms.py.\n')
        for n, p in (('ROOM_DAY', DAY), ('ROOM_NIGHT', NIGHT)):
            h.write(f'static const unsigned char {n}[{len(p)}] = {{' + ','.join(str(x) for x in p) + '};\n')
        h.write(f'static const unsigned char ROOM_CMAP[{2 * len(CMAP)}] = {{' + ','.join(f'{i},{v}' for i, v in CMAP) + '};\n')
        h.write('static const struct { unsigned desc; int x, y, scale, flip, limit; unsigned char n, cm[2*64]; } ROOM_SPRITES[8] = {\n')
        for (d, x, y, s, fl, lim), cm in SPRITES:
            h.write(f'  {{{d:#x},{x},{y},{s},{fl},{lim},{len(cm)},{{' + ','.join(f'{i},{v}' for i, v in cm) + '}},\n')
        h.write('};\n')
    print('orig_rooms.h:', len(DAY) + len(NIGHT), 'bytes')
